-- Copiando estrutura para tabela teste.compras
CREATE TABLE IF NOT EXISTS `compras` (
  `id` int NOT NULL AUTO_INCREMENT,
  `id_fornecedor` int DEFAULT NULL,
  `id_produto` int DEFAULT NULL,
  `quantidade` float NOT NULL,
  `codigo` varchar(100) DEFAULT NULL,
  `data_compra` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_id_fornecedor` (`id_fornecedor`),
  KEY `idx_id_produto` (`id_produto`),
  CONSTRAINT `fk_compras_fornecedor` FOREIGN KEY (`id_fornecedor`) REFERENCES `fornecedores` (`id`),
  CONSTRAINT `fk_compras_produto` FOREIGN KEY (`id_produto`) REFERENCES `produtos` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=603 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

